"""Pure-python age v1 implementation (X25519 + HKDF-SHA256 + ChaCha20Poly1305 + STREAM)."""
import hashlib, hmac, os, struct, base64

# ---------------- bech32 ----------------
CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
def bech32_polymod(values):
    GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3]
    chk = 1
    for v in values:
        b = chk >> 25
        chk = ((chk & 0x1ffffff) << 5) ^ v
        for i in range(5):
            chk ^= GEN[i] if ((b >> i) & 1) else 0
    return chk
def bech32_hrp_expand(hrp):
    return [ord(x) >> 5 for x in hrp] + [0] + [ord(x) & 31 for x in hrp]
def bech32_verify(hrp, data):
    return bech32_polymod(bech32_hrp_expand(hrp) + data) == 1
def bech32_create_checksum(hrp, data):
    values = bech32_hrp_expand(hrp) + data
    polymod = bech32_polymod(values + [0,0,0,0,0,0]) ^ 1
    return [(polymod >> 5*(5-i)) & 31 for i in range(6)]
def convertbits(data, frombits, tobits, pad=True):
    acc = 0; bits = 0; ret = []
    maxv = (1 << tobits) - 1
    for value in data:
        acc = (acc << frombits) | value
        bits += frombits
        while bits >= tobits:
            bits -= tobits
            ret.append((acc >> bits) & maxv)
    if pad:
        if bits:
            ret.append((acc << (tobits - bits)) & maxv)
    elif bits >= frombits or ((acc << (tobits - bits)) & maxv):
        return None
    return ret
def bech32_decode(bs):
    bs_l = bs.lower()
    pos = bs_l.rfind('1')
    hrp = bs_l[:pos]
    data = [CHARSET.find(c) for c in bs_l[pos+1:]]
    assert all(d >= 0 for d in data), "bad char"
    assert bech32_verify(hrp, data), "bad checksum"
    return hrp, bytes(convertbits(data[:-6], 5, 8, False))
def bech32_encode(hrp, payload):
    data = convertbits(payload, 8, 5)
    combined = data + bech32_create_checksum(hrp, data)
    return hrp + '1' + ''.join([CHARSET[d] for d in combined])

# ---------------- X25519 ----------------
P = 2**255 - 19
A24 = 121665
def _cswap(swap, x2, x3):
    return (x3, x2) if swap else (x2, x3)
def x25519(scalar, u):
    k = bytearray(scalar); k[0] &= 248; k[31] &= 127; k[31] |= 64
    k = int.from_bytes(bytes(k), 'little')
    u_b = bytearray(u); u_b[31] &= 127
    x1 = int.from_bytes(bytes(u_b), 'little') % P
    x2, z2, x3, z3, swap = 1, 0, x1, 1, 0
    for t in range(254, -1, -1):
        kt = (k >> t) & 1
        swap ^= kt
        x2, x3 = _cswap(swap, x2, x3); z2, z3 = _cswap(swap, z2, z3)
        swap = kt
        a = (x2 + z2) % P; aa = a*a % P
        b = (x2 - z2) % P; bb = b*b % P
        e = (aa - bb) % P
        c = (x3 + z3) % P; d = (x3 - z3) % P
        da = d*a % P; cb = c*b % P
        x3 = pow((da + cb) % P, 2, P)
        z3 = x1 * pow((da - cb) % P, 2, P) % P
        x2 = aa*bb % P
        z2 = e * ((aa + A24*e) % P) % P
    x2, x3 = _cswap(swap, x2, x3); z2, z3 = _cswap(swap, z2, z3)
    return (x2 * pow(z2, P-2, P) % P).to_bytes(32, 'little')
BASEPOINT = (9).to_bytes(32, 'little')

# ---------------- ChaCha20-Poly1305 ----------------
def _rotl(v, c): return ((v << c) & 0xffffffff) | (v >> (32 - c))
def _qr(x, a, b, c, d):
    x[a] = (x[a] + x[b]) & 0xffffffff; x[d] ^= x[a]; x[d] = _rotl(x[d], 16)
    x[c] = (x[c] + x[d]) & 0xffffffff; x[b] ^= x[c]; x[b] = _rotl(x[b], 12)
    x[a] = (x[a] + x[b]) & 0xffffffff; x[d] ^= x[a]; x[d] = _rotl(x[d], 8)
    x[c] = (x[c] + x[d]) & 0xffffffff; x[b] ^= x[c]; x[b] = _rotl(x[b], 7)
def chacha20_block(key, counter, nonce):
    st = [0x61707865, 0x3320646e, 0x79622d32, 0x6b206574]
    st += list(struct.unpack('<8I', key))
    st += [counter]
    st += list(struct.unpack('<3I', nonce))
    w = list(st)
    for _ in range(10):
        _qr(w,0,4,8,12); _qr(w,1,5,9,13); _qr(w,2,6,10,14); _qr(w,3,7,11,15)
        _qr(w,0,5,10,15); _qr(w,1,6,11,12); _qr(w,2,7,8,13); _qr(w,3,4,9,14)
    return struct.pack('<16I', *[(w[i] + st[i]) & 0xffffffff for i in range(16)])
def chacha20(key, counter, nonce, data):
    out = bytearray()
    for i in range(0, len(data), 64):
        ks = chacha20_block(key, counter + i//64, nonce)
        blk = data[i:i+64]
        out += bytes(a ^ b for a, b in zip(blk, ks))
    return bytes(out)
def poly1305(key, msg):
    r = int.from_bytes(key[:16], 'little') & 0x0ffffffc0ffffffc0ffffffc0fffffff
    s = int.from_bytes(key[16:32], 'little')
    p = (1 << 130) - 5
    acc = 0
    for i in range(0, len(msg), 16):
        blk = msg[i:i+16]
        n = int.from_bytes(blk + b'\x01' + b'\x00'*(16-len(blk)), 'little') if len(blk) < 16 \
            else int.from_bytes(blk, 'little') | (1 << 128)
        acc = ((acc + n) * r) % p
    return ((acc + s) & ((1 << 128) - 1)).to_bytes(16, 'little')
def _pad16(b): return b'\x00' * ((16 - len(b) % 16) % 16)
def aead_seal(key, nonce, pt, aad=b''):
    poly_key = chacha20_block(key, 0, nonce)[:32]
    ct = chacha20(key, 1, nonce, pt)
    mac_data = aad + _pad16(aad) + ct + _pad16(ct) + struct.pack('<QQ', len(aad), len(ct))
    return ct + poly1305(poly_key, mac_data)
def aead_open(key, nonce, ct, aad=b''):
    tag = ct[-16:]; body = ct[:-16]
    poly_key = chacha20_block(key, 0, nonce)[:32]
    mac_data = aad + _pad16(aad) + body + _pad16(body) + struct.pack('<QQ', len(aad), len(body))
    exp = poly1305(poly_key, mac_data)
    if not hmac.compare_digest(exp, tag): raise ValueError("aead auth fail")
    return chacha20(key, 1, nonce, body)

# ---------------- HKDF ----------------
def hkdf(secret, salt, info, length=32):
    prk = hmac.new(salt, secret, hashlib.sha256).digest()
    okm = b''; t = b''; i = 1
    while len(okm) < length:
        t = hmac.new(prk, t + info + bytes([i]), hashlib.sha256).digest()
        okm += t; i += 1
    return okm[:length]

def b64(b): return base64.b64encode(b).decode().rstrip('=')
def ub64(s):
    s = s + '=' * (-len(s) % 4)
    return base64.b64decode(s)

# ---------------- age header ----------------
def wrap64(s):
    return '\n'.join(s[i:i+64] for i in range(0, len(s), 64))

def x25519_stanza(file_key, recip_pub, ephemeral=None):
    e = ephemeral or os.urandom(32)
    share = x25519(e, BASEPOINT)
    ss = x25519(e, recip_pub)
    wrap = hkdf(ss, share + recip_pub, b"age-encryption.org/v1/X25519", 32)
    body = aead_seal(wrap, b'\x00'*12, file_key)
    return "-> X25519 %s\n%s\n" % (b64(share), wrap64(b64(body)))

def x25519_unwrap(identity_scalar, share, body):
    pub = x25519(identity_scalar, BASEPOINT)
    ss = x25519(identity_scalar, share)
    wrap = hkdf(ss, share + pub, b"age-encryption.org/v1/X25519", 32)
    return aead_open(wrap, b'\x00'*12, body)

def make_header(file_key, stanzas):
    hdr = "age-encryption.org/v1\n" + ''.join(stanzas) + "---"
    mk = hkdf(file_key, b'', b"header", 32)
    mac = hmac.new(mk, hdr.encode(), hashlib.sha256).digest()
    return (hdr + " " + b64(mac) + "\n").encode()

def payload_key(file_key, nonce):
    return hkdf(file_key, nonce, b"payload", 32)

CHUNK = 65536
def stream_nonce(counter, final):
    return counter.to_bytes(11, 'big') + (b'\x01' if final else b'\x00')

def stream_encrypt(pkey, chunks):
    """chunks: list of (plaintext_bytes, final_flag)"""
    out = b''
    for i, (pt, fin) in enumerate(chunks):
        out += aead_seal(pkey, stream_nonce(i, fin), pt)
    return out

