#!/usr/bin/env python3
"""Run a command with stdin/stdout/stderr all attached to a single PTY.
Usage: ptyrun.py [--in-data STR] [--sep] -- cmd args...
Prints:  ---EXIT <code>--- then the raw pty output (repr) to stdout.
Options:
  --stdout-pty / --all-pty (default all-pty)
"""
import os, sys, pty, select, termios, struct, fcntl, signal, time, argparse

def run(cmd, feed=b'', mode='all', timeout=15.0, env=None):
    mpty, spty = pty.openpty()
    # make raw-ish
    try:
        attrs = termios.tcgetattr(spty)
        attrs[3] = attrs[3] & ~termios.ECHO
        termios.tcsetattr(spty, termios.TCSANOW, attrs)
    except Exception:
        pass
    r_out, w_out = os.pipe()
    r_err, w_err = os.pipe()
    r_in, w_in = os.pipe()
    pid = os.fork()
    if pid == 0:
        os.setsid()
        fcntl.ioctl(spty, termios.TIOCSCTTY, 0)
        if mode == 'all':
            os.dup2(spty, 0); os.dup2(spty, 1); os.dup2(spty, 2)
        elif mode == 'stdout':   # only stdout is a tty
            os.dup2(r_in, 0); os.dup2(spty, 1); os.dup2(w_err, 2)
        elif mode == 'stderr':   # only stderr is a tty
            os.dup2(r_in, 0); os.dup2(w_out, 1); os.dup2(spty, 2)
        elif mode == 'stdin':    # only stdin is a tty
            os.dup2(spty, 0); os.dup2(w_out, 1); os.dup2(w_err, 2)
        elif mode == 'stdin_stderr':  # stdin+stderr tty, stdout pipe
            os.dup2(spty, 0); os.dup2(w_out, 1); os.dup2(spty, 2)
        for fd in (mpty, spty, r_out, w_out, r_err, w_err, r_in, w_in):
            try:
                if fd > 2: os.close(fd)
            except Exception: pass
        if env is not None:
            os.execve(cmd[0], cmd, env)
        os.execv(cmd[0], cmd)
        os._exit(127)
    os.close(spty); os.close(w_out); os.close(w_err); os.close(r_in)
    if feed:
        os.write(w_in, feed)
    os.close(w_in)
    bufs = {mpty: b'', r_out: b'', r_err: b''}
    if feed and mode == 'all':
        time.sleep(0.15)
        os.write(mpty, feed)
    open_fds = [mpty, r_out, r_err]
    t0 = time.time()
    while open_fds and time.time() - t0 < timeout:
        rl, _, _ = select.select(open_fds, [], [], 0.2)
        for fd in rl:
            try:
                d = os.read(fd, 65536)
            except OSError:
                d = b''
            if not d:
                open_fds.remove(fd)
            else:
                bufs[fd] += d
    try:
        _, status = os.waitpid(pid, os.WNOHANG)
        if _ == 0:
            time.sleep(0.3)
            _, status = os.waitpid(pid, os.WNOHANG)
            if _ == 0:
                os.kill(pid, signal.SIGKILL); _, status = os.waitpid(pid, 0)
    except ChildProcessError:
        status = 0
    for fd in [mpty, r_out, r_err]:
        try: os.close(fd)
        except Exception: pass
    if os.WIFEXITED(status): code = os.WEXITSTATUS(status)
    elif os.WIFSIGNALED(status): code = 128 + os.WTERMSIG(status)
    else: code = -1
    return code, bufs[mpty], bufs[r_out], bufs[r_err]

if __name__ == '__main__':
    ap = argparse.ArgumentParser()
    ap.add_argument('--feed', default='')
    ap.add_argument('--mode', default='all')
    ap.add_argument('--timeout', type=float, default=15.0)
    ap.add_argument('cmd', nargs=argparse.REMAINDER)
    a = ap.parse_args()
    cmd = a.cmd[1:] if a.cmd and a.cmd[0] == '--' else a.cmd
    feed = a.feed.encode().decode('unicode_escape').encode('utf-8', 'surrogateescape')
    code, tty, out, err = run(cmd, feed, a.mode, a.timeout)
    print("EXIT=%d" % code)
    print("TTY=%r" % tty)
    print("PIPEOUT=%r" % out)
    print("PIPEERR=%r" % err)
